function SectionTitle({ icon, children }: { icon: string; children: React.ReactNode }) {
  return (
    <div className="flex items-center gap-2 text-[10px] text-slate-500 uppercase tracking-wider font-semibold mb-2.5 pb-2 mt-3" style={{ borderBottom: "1px solid rgba(30,45,74,0.35)" }}>
      <span>{icon}</span>{children}
    </div>
  );
}

function InputRow({ label, w, val, set, ph }: { label: string; w: string; val: string; set: (v: string) => void; ph?: string }) {
  return (
    <div className="flex items-center gap-2 mb-2 flex-wrap">
      <span className="text-[11px] text-slate-500 min-w-[160px] font-medium">{label}</span>
      <input type="number" className="px-3 py-2 rounded-lg text-[13px] font-bold text-center focus:outline-none" style={{ width: w, background: "rgba(15,23,42,0.8)", border: "1px solid rgba(30,45,74,0.6)", color: "#e2e8f0" }} placeholder={ph} value={val} onChange={(e) => set(e.target.value)} />
    </div>
  );
}

function Modal({ onClose, title, children }: { onClose: () => void; title: string; children: React.ReactNode }) {
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center" style={{ background: "rgba(0,0,0,0.7)", backdropFilter: "blur(8px)" }} onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="rounded-2xl p-6 w-[90%] max-w-[400px]" style={{ background: "linear-gradient(180deg, #111827, #0d1117)", border: "1px solid rgba(30,45,74,0.6)", boxShadow: "0 20px 60px rgba(0,0,0,0.5)" }}>
        <h3 className="text-[15px] font-bold mb-4 text-slate-200">{title}</h3>
        {children}
      </div>
    </div>
  );
}

function ModalField({ label, placeholder, value, onChange, hint }: { label: string; placeholder: string; value: string; onChange: (v: string) => void; hint?: string }) {
  return (
    <div className="mb-3">
      <label className="block text-[10px] text-slate-500 mb-1.5 uppercase tracking-wider font-medium">{label}</label>
      <input className="w-full px-3 py-2.5 rounded-lg text-xs focus:outline-none placeholder:text-slate-600 transition-all" style={{ background: "rgba(15,23,42,0.8)", border: "1px solid rgba(30,45,74,0.6)", color: "#e2e8f0" }} placeholder={placeholder} value={value} onChange={(e) => onChange(e.target.value)} />
      {hint && <div className="text-[9px] text-cyan-400 mt-1">{hint}</div>}
    </div>
  );
}